#!/bin/bash
# Instala en el backend: tabla Intento, IA adaptativa RF4, niveles RF13, logros RF6 y estado del jugador.
# Uso (en la terminal del Codespace):  bash instalar_progreso.sh
set -e
cd /workspaces/dislexia-godot

echo "1/5 Copiando archivos nuevos..."
echo "" | base64 -d | tar xzf -

echo "2/5 Registrando los modelos y las rutas..."
grep -q "from .progreso import" backend/app/models/__init__.py || \
  printf '\nfrom .progreso import Intento, DificultadMundo, CambioDificultad, Logro, EstadoJugador\n' >> backend/app/models/__init__.py
python - <<'PY'
p = "backend/app/__init__.py"
s = open(p, encoding="utf-8-sig").read()
nuevo = ""
if "ia_bp" not in s:
    nuevo += "    from app.routes.ia_routes import ia_bp\n    app.register_blueprint(ia_bp)\n\n"
if "progreso_bp" not in s:
    nuevo += "    from app.routes.progreso_routes import progreso_bp\n    app.register_blueprint(progreso_bp)\n\n"
if nuevo:
    i = s.rindex("    return app")
    s = s[:i] + nuevo + s[i:]
    open(p, "w", encoding="utf-8").write(s)
PY

echo "3/5 Copia de seguridad de la base de datos (backend/dislexia_respaldo.db)..."
cp backend/dislexia.db backend/dislexia_respaldo.db

echo "4/5 Creando las tablas nuevas..."
(cd backend && FLASK_APP=run.py flask db upgrade)

echo "5/5 Probando..."
(cd backend && pip install -q pytest > /dev/null 2>&1; OLLAMA_URL=http://127.0.0.1:9 python -m pytest -q tests 2>&1 | tail -1)

echo ""
echo "Listo. Si el backend estaba prendido, se reinicia solo. Comprueba con:"
echo "  curl localhost:5000/api/health"
